INSERT /* AppformMapper.insertMcpRequest 서식지 정보 저장  */
INTO MCP_REQUEST@DL_MCP (
    REQUEST_KEY              --가입신청_키
    , MANAGER_CODE             --매니저_코드
    , AGENT_CODE               --대리점_코드
    , SERVICE_TYPE             --서비스구분
    , OPER_TYPE                --업무구분
    , CSTMR_TYPE               --고객구분
    , RES_CODE                 --예약등록_코드
    , RES_MSG                  --예약등록_메세지
    , RES_NO                   --예약등록_예약번호
    , CLAUSE_PRI_COLLECT_FLAG  --약관_개인정보_수집_동의
    , CLAUSE_PRI_OFFER_FLAG    --약관_개인정보_제공_동의
    , CLAUSE_ESS_COLLECT_FLAG  --약관_고유식별정보_수집이용제공_동의
    , CLAUSE_PRI_TRUST_FLAG    --약관_개인정보_위탁_동의
    , CLAUSE_PRI_AD_FLAG       --개인정보 처리 위탁 및 고객 혜택 제공을 위한 광고 수신 동의
    , CLAUSE_CONFIDENCE_FLAG   --약관_신용정보_이용_동의
    , CLAUSE_JEHU_FLAG         --제휴_서비스동의
    , ONLINE_AUTH_TYPE         --온라인_인증방식
    , ONLINE_AUTH_INFO         --온라인_인증정보
    , PSTATE                   --신청서_상태
    , REQUEST_STATE_CODE       --가입진행_코드
    , OPEN_NO                  --개통번호
    , FILE01                   --파일01
    , FILE01_MASK              --파일01_마스크
    , FAXYN                    --팩스사용여부
    , FAXNUM                   --팩스번호
    , SCAN_ID                  --스캐너아이디
    , ON_OFF_TYPE              --온라인오프라인구분
    , RIP                      --등록아이피
    , OPEN_REQ_DATE            --
    , SYS_RDATE                --등록일시
    , REQ_WANT_NUMBER
    , REQ_WANT_NUMBER2
    , REQ_WANT_NUMBER3
    , REQ_BUY_TYPE
    , REQ_MODEL_NAME
    , REQ_MODEL_COLOR
    , REQ_PHONE_SN
    , REQ_USIM_SN
    , REQ_PAY_TYPE
    , REQ_ADDITION
    , SHOP_CD
    , APP_FORM_YN
    , REQ_IN_DAY               --가입신청일
    , CONTRACT_NUM
    , ETC_SPECIAL              --기타/특약사항
    , REQ_USIM_NAME            --USIM 모델명
    , PHONE_PAYMENT            --휴대폰결제 이용여부
    , REQ_ADDITION_PRICE       --부가서비스금액
    , CNTPNT_SHOP_ID           --채널점아이디_판매점코드
    , OPEN_MARKET_REFERER
    , NW_BLCK_AGRM_YN          --네트워크차단동의여부
    , APP_BLCK_AGRM_YN         --어플리케이션차단동의여부
    , APP_CD                   --APP구분코드
    , PROD_ID                  --상품아이디
    , BANNER_CD                --배너코드
    , CRET_ID                  --생성자아이디(로그인아이디)
    , SNTY_COLOR_CD            --색상코드
    , SNTY_CAPAC_CD            --단품용량코드
    , PROD_TYPE                -- 상품 분류 (일반 :01, 0원 상품 :02)
    , CLAUSE_RENTAL_SERVICE    --중고렌탈 프로그램 서비스 이용에 대한 동의서
    , CLAUSE_RENTAL_MODEL_CP   --단말배상금 안내사항
    , CLAUSE_RENTAL_MODEL_CP_PR --단말배상금(부분파손) 안내사항
    , CLAUSE_MPPS35_FLAG        --선불 M PPS 요금제_동의
    , CLAUSE_FINANCE_FLAG       --개인(신용)정보 처리 및 보험가입 동의서
